        string FormatValue(object value)
        {
            if (value == null) return "NULL";
            if (value is string || value is char) return $"'{value}'";
            return value.ToString();
        }
        public static DataTable CreateDataTable()
		{
			DataTable dt = new DataTable();

			dt.Columns.Add("Imei", typeof(string));
			dt.Columns.Add("FileName", typeof(string));
			dt.Columns.Add("Channel", typeof(string));
			dt.Columns.Add("GpsTime", typeof(DateTime));

			return dt;
		}

		public static List<Pushing_Dashcam_History_Data> ProcessData(string imei, string fileNameList)
		{
			List<Pushing_Dashcam_History_Data> dashcamDataList = new List<Pushing_Dashcam_History_Data>();
			try
			{
				string[] fileNames = fileNameList.Split(',');

				foreach (string fileName in fileNames)
				{
					if (!string.IsNullOrWhiteSpace(fileName))
					{
						string dateTimePart = fileName.Substring(0, 19);
                        DateTime gpsTime = DateTime.ParseExact(dateTimePart, "yyyy_MM_dd_HH_mm_ss", CultureInfo.InvariantCulture);
                        
                        string channel = fileName.Substring(21, 1);
						Pushing_Dashcam_History_Data data = new Pushing_Dashcam_History_Data
						{
							Imei = imei,
							FileName = fileName,
							GpsTime = gpsTime,
							Channel = channel
						};

						dashcamDataList.Add(data);
					}
				}
			}
			catch (Exception ex)
			{
            }
			return dashcamDataList;
		}


	}
